function findTwoRepeats(nums: number[]): number[] {
  const n = nums.length - 2;
  let both = 0;
  for (const v of nums) both ^= v;
  for (let i = 0; i < n; i++) both ^= i;
  const bit = both & -both; // lowest bit where x and y differ
  let x = 0;
  for (const v of nums) if (v & bit) x ^= v;
  for (let i = 0; i < n; i++) if (i & bit) x ^= i;
  return [x, both ^ x];
}

